// Fork of 1211 chars "A Crown of Thorns" by StormOfTheVoid. https://shadertoy.com/view/l33fzl

void mainImage( out vec4 O, vec2 U )
{
    U -= .5*R;    
    float r = 6.28/s, d;

    for( O*=d ; d < 6.28 ; d += r  )
        U *= mat2(cos(r),sin(r),-sin(r),cos(r)),
        O.rgb +=   texture(iChannel0, .5 + U/R ).rgb
                 *4.8 / q * normalize( 1. + SC(d).yyx *vec3 (1,-1,1) ); 	

    r = 1.25; // ← saturation  ↓ luminance
	O = r * O + ( 1.-r) * dot( vec3( .31, .61, .08 ), O.rgb );

}

void mainImage( out vec4 O, vec2 u )
{
    vec2  U = 3.3*( u - .5*R ) / R.y, V;      
    float j,g,h;

    for( O*=g ; j < 1070.*n; j++ ) 
        g = mod( j/q , 6.28+3. ) - 3.14 -.75,
        h = 150.*.14 / exp( g*g ),
        V = U + SC(j/q - iTime*.1),
        O.rgb +=   exp2( - 150.* abs( dot(V,V) - h ) / sqrt(h) ); 	        
}

const float n = 1.,
            s = 20.,
            q = 3e2*n;

#define R     iResolution.xy   
#define SC(a) vec2(sin(a),cos(a))
